/// Handler for: `eth_sendRawTransaction`
async fn send_raw_transaction(&self, tx: Bytes) -> RpcResult<B256> {
    trace!(target: "rpc::eth", ?tx, "Serving eth_sendRawTransaction");
    Ok(EthTransactions::send_raw_transaction(self, tx).await?)
}

/// Decodes and recovers the transaction and submits it to the pool.
///
/// Returns the hash of the transaction.
fn send_raw_transaction(
    &self,
    tx: Bytes,
) -> impl Future<Output = Result<B256, Self::Error>> + Send {
    async move {
        let pool_transaction = self.recover_raw_pool_transaction(&tx)?;
        self.send_pool_transaction(
            TransactionOrigin::Local,
            WithEncoded::new(tx, pool_transaction),
        )
        .await
    }
}

/// Decodes and recovers a raw pool transaction, sharing sender recovery when configured.
fn recover_raw_pool_transaction(&self, tx: &[u8]) -> Result<PoolTx<Self::Pool>, Self::Error> {
    match self.eth_api_settings().sender_recovery_cache.as_ref() {
        Some(cache) => {
            <PoolTx<Self::Pool> as PoolTransaction>::recover_raw_transaction_with_cache(
                tx, cache,
            )
        }
        None => <PoolTx<Self::Pool> as PoolTransaction>::recover_raw_transaction(tx),
    }
    .map_err(Self::Error::from_eth_err)
}

async fn send_pool_transaction(
    &self,
    origin: reth_transaction_pool::TransactionOrigin,
    tx: WithEncoded<PoolTx<Self::Pool>>,
) -> Result<B256, Self::Error> {
    let (tx, mut pool_transaction) = tx.split();

    // Optionally convert legacy blob sidecars to EIP-7594 format when Osaka is active
    // This is opt-in via --rpc.force-blob-sidecar-upcasting
    if self.inner.force_blob_sidecar_upcasting() && pool_transaction.is_eip4844() {
        let EthBlobTransactionSidecar::Present(sidecar) = pool_transaction.take_blob() else {
            return Err(EthApiError::PoolError(RpcPoolError::Eip4844(
                Eip4844PoolTransactionError::MissingEip4844BlobSidecar,
            )));
        };
        let sidecar = sidecar.into_sidecar();

        let sidecar = match sidecar {
            BlobTransactionSidecarVariant::Eip4844(sidecar) => {
                let latest = self
                    .provider()
                    .latest_header()?
                    .ok_or(EthApiError::HeaderNotFound(BlockId::latest()))?;
                // Convert to EIP-7594 if next block is Osaka
                if self
                    .provider()
                    .chain_spec()
                    .is_osaka_active_at_timestamp(latest.timestamp().saturating_add(12))
                {
                    BlobTransactionSidecarVariant::Eip7594(
                        self.blob_sidecar_converter().convert(sidecar).await.ok_or_else(
                            || {
                                RpcPoolError::Eip4844(
                                    Eip4844PoolTransactionError::InvalidEip4844Blob(
                                        BlobTransactionValidationError::InvalidProof,
                                    ),
                                )
                            },
                        )?,
                    )
                } else {
                    BlobTransactionSidecarVariant::Eip4844(sidecar)
                }
            }
            sidecar => sidecar,
        };

        pool_transaction =
            EthPoolTransaction::try_from_eip4844(pool_transaction.into_consensus(), sidecar)
                .ok_or_else(|| {
                    RpcPoolError::Eip4844(
                        Eip4844PoolTransactionError::MissingEip4844BlobSidecar,
                    )
                })?;
    }

    // forward the transaction to the specific endpoint if configured.
    if let Some(client) = self.raw_tx_forwarder() {
        tracing::debug!(target: "rpc::eth", hash = %pool_transaction.hash(), "forwarding raw transaction to forwarder");
        let rlp_hex = hex::encode_prefixed(&tx);

        // broadcast raw transaction to subscribers if there is any.
        self.broadcast_raw_transaction(tx);

        let hash =
            client.request("eth_sendRawTransaction", (rlp_hex,)).await.inspect_err(|err| {
                tracing::debug!(target: "rpc::eth", %err, hash=% *pool_transaction.hash(), "failed to forward raw transaction");
            }).map_err(EthApiError::other)?;

        // Retain tx in local tx pool after forwarding, for local RPC usage.
        let _ = self.inner.add_pool_transaction(origin, pool_transaction).await;

        return Ok(hash);
    }

    // broadcast raw transaction to subscribers if there is any.
    self.broadcast_raw_transaction(tx);

    let AddedTransactionOutcome { hash, .. } =
        self.inner.add_pool_transaction(origin, pool_transaction).await?;

    Ok(hash)
}

async fn add_transaction(
    &self,
    origin: TransactionOrigin,
    transaction: Self::Transaction,
) -> PoolResult<AddedTransactionOutcome> {
    let tx = self.validate(origin, transaction).await;
    let mut results = self.pool.add_transactions(origin, std::iter::once(tx));
    results.pop().expect("result length is the same as the input")
}

async fn add_transactions(
    &self,
    origin: TransactionOrigin,
    transactions: Vec<Self::Transaction>,
) -> Vec<PoolResult<AddedTransactionOutcome>> {
    if transactions.is_empty() {
        return Vec::new()
    }
    let validated =
        self.pool.validator().validate_transactions_with_origin(origin, transactions).await;
    self.pool.add_transactions(origin, validated)
}

async fn add_transactions_with_origins(
    &self,
    transactions: Vec<(TransactionOrigin, Self::Transaction)>,
) -> Vec<PoolResult<AddedTransactionOutcome>> {
    if transactions.is_empty() {
        return Vec::new()
    }
    let origins: Vec<_> = transactions.iter().map(|(origin, _)| *origin).collect();
    let validated = self.pool.validator().validate_transactions(transactions).await;
    self.pool.add_transactions_with_origins(origins.into_iter().zip(validated))
}

pub trait EthTransactions: LoadTransaction<Provider: BlockReaderIdExt> {
    /// Returns a handle for signing data.
    ///
    /// Signer access in default (L1) trait method implementations.
    fn signers(&self) -> &SignersForRpc<Self::Provider, Self::NetworkTypes>;

    /// Returns a list of addresses owned by provider.
    fn accounts(&self) -> Vec<Address> {
        self.signers().read().iter().flat_map(|s| s.accounts()).collect()
    }

    /// Returns the timeout duration for `send_raw_transaction_sync` RPC method.
    fn send_raw_transaction_sync_timeout(&self) -> Duration {
        self.eth_api_settings().send_raw_transaction_sync_timeout
    }

impl<N, Rpc> EthTransactions for EthApi<N, Rpc>
where
    N: RpcNodeCore,
    EthApiError: FromEvmError<N::Evm>,
    Rpc: RpcConvert<Primitives = N::Primitives, Error = EthApiError>,
{
    #[inline]
    fn signers(&self) -> &SignersForRpc<Self::Provider, Self::NetworkTypes> {
        self.inner.signers()
    }
